cd ~/.config/opencode/agents && python3 - <<'EOF'
import glob, re, sys
slugs = ["oh-my-opencode-slim","pi","ruview","openship","code-review-graph","i-have-adhd","orca","omniroute","mattpocock-skills","worldmonitor","ai-agent-book","onp-spec-driven"]
ok = True
for s in slugs:
    path = f"{s}.md"
    txt = open(path).read()
    fm = txt.split("---")[1] if txt.startswith("---") else ""
    errs = []
    if "mode: primary" in fm: errs.append("mode:primary")
    if re.search(r"^origin:", fm, re.M): errs.append("origin")
    if re.search(r"^tags:", fm, re.M): errs.append("tags")
    if ">-" in fm or "|-" in fm: errs.append("folded-scalar")
    if not re.search(r"^mode: subagent$", fm, re.M): errs.append("no-mode-subagent")
    # tools must be boolean map
    for k in ["bash","read","edit","webfetch"]:
        if not re.search(rf"^{k}: (true|false)$", fm, re.M): errs.append(f"tools:{k}")
    if not re.search(r"^description: ", fm, re.M): errs.append("no-description")
    if not re.search(r"## Origem", txt): errs.append("no-Origem-body")
    # description must be single line
    for line in fm.splitlines():
        if line.startswith("description:") and line.count("\n")==0 and not line.endswith('"') and not line.endswith("'"):
            pass
    dlines = [l for l in fm.splitlines() if l.startswith("description:")]
    if len(dlines)!=1: errs.append(f"description-multi ({len(dlines)})")
    if errs:
        print(f"FAIL {s}: {errs}"); ok=False
    else:
        print(f"OK   {s}")
sys.exit(0 if ok else 1)
EOF
